240	  /** Builds the queue table HTML string from the entries array.
241	   *  Returns the complete <table>…</table> markup ready to be assigned to
242	   *  container.innerHTML. */
243	  function _buildQueueHtml(entries) {
244	    var html = '<table class="table orch-queue-table"><thead>' +
245	      '<tr><th></th><th>Plan</th><th>Status</th><th>Elapsed</th><th>Progress</th><th>Actions</th></tr>' +
246	      '</thead><tbody>';
247	    entries.forEach(function (entry) {
248	      var id         = entry.id || '';
249	      var status     = entry.effectiveStatus || 'pending';
250	      var planName   = _orchBasename(entry.planPath || '');

251	      var elapsed    = _orchElapsed(entry.startedAt);
252	      var isExpanded = !!expandedIds[id];
253	      var statusBadgeHtml = '<span class="badge badge-' + escapeHtml(status) + '">' +
254	        escapeHtml(_orchStatusLabel(status)) + '</span>';
255	      // Progress cell: badge + text summary + optional log link.
256	      var progressHtml = OrchestratorWidgets.renderProgressBadge(entry.lastAction || null);
257	      if (entry.progress) {
258	        progressHtml += ' <span class="orch-progress-text">' + escapeHtml(entry.progress) + '</span>';
259	      }
260	      if (entry.logFilename && entry.expectedSlug) {
261	        progressHtml += ' <a href="#/projects/' +
262	          encodeURIComponent(entry.expectedSlug) + '/runs/' +
263	          encodeURIComponent(entry.logFilename) + '" class="orch-log-link">View Log →</a>';
264	      } else if (!entry.progress) {
265	        progressHtml += ' <span class="text-muted">Waiting for log…</span>';
266	      }
267	      html += '<tr class="orch-queue-row orch-row-' + escapeHtml(status) + '"' +
268	        ' data-entry-id="' + escapeHtml(id) + '">';
269	      html += '<td class="orch-toggle-cell">' +
270	        '<button type="button" class="orch-row-toggle btn-icon" data-entry-id="' + escapeHtml(id) + '">' +
271	        (isExpanded ? '▼' : '▶') + '</button></td>';
272	      html += '<td class="orch-plan-cell" title="' + escapeHtml(entry.planPath || '') + '">' +
273	        escapeHtml(planName) + '</td>';
274	      html += '<td class="orch-status-cell">' + statusBadgeHtml + '</td>';
275	      html += '<td class="orch-elapsed-cell">' + escapeHtml(elapsed) + '</td>';
276	      html += '<td class="orch-progress-cell">' + progressHtml + '</td>';
277	      html += '<td class="orch-actions-cell" data-actions-for="' + escapeHtml(id) + '"></td>';
278	      html += '</tr>';
279	      if (isExpanded) {
280	        html += '<tr class="orch-log-row" data-entry-id="' + escapeHtml(id) + '">' +
281	          '<td colspan="6">' +
282	          '<div class="orch-log-preview" id="orch-log-' + escapeHtml(id) + '"></div>' +
283	          '</td></tr>';
284	      }
285	    });
286	    html += '</tbody></table>';
287	    return html;
