341	  /** Starts log previews for all currently expanded rows and registers their
342	   *  cleanup callbacks in _orchLogPreviewCleanups.
343	   *
344	   *  Closure dependencies (from renderOrchestrator() scope):
345	   *    `expandedIds`              — read to determine which rows are currently
346	   *                                 expanded; only those rows get a live preview.
347	   *    `_orchLogPreviewCleanups`  — the module-level log-preview cleanup registry;
348	   *                                 each preview's cleanup callback is pushed here
349	   *                                 so it is cancelled when renderOrchestrator() or
350	   *                                 refreshQueue() next runs.
351	   *
352	   *  Note: _orchStatusPollCleanups is a separate registry for status-poll timers
353	   *  and is intentionally excluded from this function's scope. Status-poll cleanups
354	   *  are only drained by renderOrchestrator() (full view re-render), never by
355	   *  refreshQueue() or _mountLogPreviews(). */
356	  function _mountLogPreviews(container, entries) {
357	    entries.forEach(function (entry) {
358	      var id = entry.id || '';
359	      if (!expandedIds[id] || !entry.logFilename || !entry.expectedSlug) return;
360	      var previewEl = document.getElementById('orch-log-' + id);
361	      if (!previewEl) return;
362	      var cleanup = OrchestratorWidgets.renderLogPreview(
363	        previewEl,
364	        entry.expectedSlug,
365	        entry.logFilename
366	      );
367	      _orchLogPreviewCleanups.push(cleanup);
368	    });
369	  }
