373	  function renderQueueTable(container, entries) {
374	    // Save viewport scroll position before replacing innerHTML — the document
375	    // viewport is the scrolling context (not the container, which has no
376	    // overflow CSS), so window.scrollY is the correct save/restore target.
377	    var savedScrollY = window.scrollY;
378	
379	    if (!entries.length) {
380	      container.innerHTML = '<p class="text-muted orch-empty-queue">No active runs in the queue.</p>';
381	      return;
382	    }
383	
384	    _clearSuccessBanner();
385	    container.innerHTML = _buildQueueHtml(entries);
386	    _bindQueueActions(container, entries);
387	    _mountLogPreviews(container, entries);
388	
389	    // Restore scroll position after all DOM manipulation is complete.
390	    // Must be the last statement so intermediate DOM mutations do not
391	    // interfere with the restored position.
392	    window.scrollTo(0, savedScrollY);
393	  }
394	
395	  // 8. Kick off the first queue fetch and register the polling interval.
396	  refreshQueue();
397	  Router._setPolling(refreshQueue, 5000);
398	}
