404	/** Returns the final path segment (filename or folder name). */
405	function _orchBasename(path) {
406	  var parts = String(path).replace(/\\/g, '/').split('/');
407	  return parts[parts.length - 1] || path;
408	}
409	
410	/** Human-readable label for an effectiveStatus value. */
411	function _orchStatusLabel(status) {
412	  if (status === 'started') return 'Started';
413	  if (status === 'dead')    return 'Dead';
414	  return 'Pending';
415	}
416	
417	/** Formats elapsed time from an ISO start timestamp. */
418	function _orchElapsed(startedAt) {
419	  if (!startedAt) return '—';
420	  try {
421	    var diff = Date.now() - new Date(startedAt).getTime();
422	    if (isNaN(diff) || diff < 0) return '—';
423	    var secs = Math.round(diff / 1000);
424	    if (secs < 60)  return secs + 's';
425	    var mins = Math.floor(secs / 60);
426	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
427	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
428	  } catch (_) {
429	    return '—';
430	  }
431	}

